<script setup lang="ts">
const route = useRoute()

// Online/total count published by the dashboard; shown compactly in the
// mobile top nav next to the status dot.
const navStatus = useState('hans-nav-status', () => ({ online: 0, total: 0 }))

const showIntro = ref(false)

onMounted(() => {
  const seen = localStorage.getItem('hans-intro-seen')
  if (!seen) showIntro.value = true
})

function onIntroDone() {
  showIntro.value = false
  localStorage.setItem('hans-intro-seen', '1')
}

// Cursor glow dot — desktop only
const isPointerFine = ref(false)
const dotX = ref(-100)
const dotY = ref(-100)
let rafId: number | null = null

onMounted(() => {
  isPointerFine.value = window.matchMedia('(pointer: fine)').matches
  if (!isPointerFine.value) return

  let targetX = -100
  let targetY = -100
  let curX = -100
  let curY = -100

  window.addEventListener('mousemove', (e) => {
    targetX = e.clientX - 10
    targetY = e.clientY - 10
  })

  function animate() {
    curX += (targetX - curX) * 0.18
    curY += (targetY - curY) * 0.18
    dotX.value = curX
    dotY.value = curY
    rafId = requestAnimationFrame(animate)
  }
  rafId = requestAnimationFrame(animate)
})

onUnmounted(() => {
  if (rafId !== null) cancelAnimationFrame(rafId)
})
</script>

<style scoped>
.cursor-dot {
  position: fixed;
  top: 0;
  left: 0;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  pointer-events: none;
  z-index: 9999;
  background: radial-gradient(circle, rgba(220, 160, 20, 0.45) 0%, rgba(220, 160, 20, 0.45) 50%, transparent 88%);
  will-change: transform;
  mix-blend-mode: screen;
}
</style>
